package com.flippingfriend.companion;
import java.util.ArrayList; import java.util.List;
/** Pure fail-closed binding of generated quantities to existing fill and market authority. */
final class BuyReplacementQuantityFillInputContextComposer {
 BuyReplacementQuantityFillInputContext compose(BuyReplacementQuantityGridCandidateSet grid,BuyReplacementCandidateFillInputContext fill,double season,long marketAt,long at){if(grid==null||fill==null||at<grid.getComposedAt()||at<fill.getComposedAt()||grid.getComposedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||fill.getComposedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||marketAt<0||marketAt>at||marketAt+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||fill.getHistoryObservedAt()<0||fill.getHistoryObservedAt()>at||fill.getFillCurve()==null||fill.getFillCurve().isEmpty()||!Double.isFinite(fill.getEffectiveHorizonHours())||fill.getEffectiveHorizonHours()<=0||!Double.isFinite(season)||season<=0||grid.getCandidates()==null||grid.getCandidates().isEmpty()||!same(grid,fill))return null;List<BuyReplacementQuantityFillInput> out=new ArrayList<>(grid.getCandidates().size());for(BuyReplacementQuantityGridCandidate c:grid.getCandidates()){if(c==null||c.getBuyPrice()<=0||c.getSellPrice()<=c.getBuyPrice()||c.getFillableQuantity()!=grid.getExactRemainderQuantity()||c.getQuantity()<1||c.getQuantity()>c.getFillableQuantity()||c.getSizeGridIndex()<0||!Double.isFinite(c.getSizeShare())||c.getSizeShare()<=0)return null;out.add(new BuyReplacementQuantityFillInput(c));}return new BuyReplacementQuantityFillInputContext(grid,out,fill.getFillCurve(),fill.getEffectiveHorizonHours(),season,fill.getHistoryObservedAt(),marketAt,at);}
 private static boolean same(BuyReplacementQuantityGridCandidateSet g,BuyReplacementCandidateFillInputContext f){return g.getItemId()==f.getItemId()&&g.getExactRemainderQuantity()==f.getExactRemainderQuantity()&&eq(g.getIntentId(),f.getIntentId())&&eq(g.getOriginalOfferIdentity(),f.getOriginalOfferIdentity())&&eq(g.getRecommendationId(),f.getRecommendationId())&&eq(g.getAppetiteName(),f.getAppetiteName());} private static boolean eq(String a,String b){return a!=null&&a.equals(b);}
}
